function convert(s: string, numRows: number): string {
  // Одна строка или строк не меньше, чем символов, — зигзага нет
  if (numRows === 1 || numRows >= s.length) return s;

  // Для каждой строки зигзага копим её символы
  const rows: string[] = new Array(numRows).fill('');
  let row = 0;
  let step = 1; // +1 — идём вниз, -1 — вверх по диагонали

  for (const ch of s) {
    rows[row] += ch;

    // На верхней и нижней строке меняем направление
    if (row === 0) step = 1;
    else if (row === numRows - 1) step = -1;

    row += step;
  }

  // Читаем построчно
  return rows.join('');
}

// Время: O(n) — каждый символ кладём один раз
// Память: O(n) — строки зигзага
